import React from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
// ... بقية الاستيرادات الموجودة في كودك ...

// وظيفة لحماية المسارات
const ProtectedRoute = ({ children }) => {
  const token = localStorage.getItem('token');
  return token ? children : <Navigate to="/auth" replace />;
};

function App() {
  return (
    <Router>
      <div className="flex flex-col min-h-screen">
        <Navbar />
        <main className="flex-grow">
          <Routes>
            <Route path="/" element={<HomePage />} />
            <Route path="/opportunities" element={<OpportunitiesPage />} />
            <Route path="/auth" element={<AuthPage />} />
            
            {/* صفحات محمية: لا تفتح إلا بعد تسجيل الدخول */}
            <Route path="/students" element={
              <ProtectedRoute> <StudentsDashboard/> </ProtectedRoute>
            }/>
            <Route path="/profile" element={
              <ProtectedRoute> <ProfilePage /> </ProtectedRoute>
            }/>
            <Route path="/myapplication" element={
              <ProtectedRoute> <MyApplicationsPage/> </ProtectedRoute>
            }/>
            
            <Route path="/opportunity/:id" element={<OpportunityDetailPage/>}/>
          </Routes>
        </main>
        <Footer />
      </div>
    </Router>
  );
}

export default App;
